        neighbors = limits.get(node, {})
        for neighbor in sorted(neighbors.keys()):
            weight = neighbors[neighbor]
            new_bottleneck = min(bottleneck, weight)
            new_length = length + 1
            neighbor_best = best.get(neighbor, (-1.0, float('inf')))
            if new_bottleneck > neighbor_best[0] or (new_bottleneck == neighbor_best[0] and new_length < neighbor_best[1]):
